// ─────────────────────────────────────────────────────────────────────────────
// ADVERB SCALES — reference screens (Session 42, PRD_Adverb_Scales.md)
//
// Data: appData.adverbScales  ←  js/data.js  ←  data/adverb-scales.json
//       (generated by _factory/adverb-scales/generate.py — never hand-edit)
//
// Two screens:
//   screen-adverb-scales   list of all axes
//   screen-adverb-scale    one axis, drawn vertically pole → pole (or a grid)
//
// The ordering exercises (type 'scale_choice') live in exercises-adverbs.json and
// are played by the Main engine — this file only renders reference material and
// starts sessions through openExercise(), the same door every module uses.
// ─────────────────────────────────────────────────────────────────────────────

let _scaleAxisId = null;

function _scaleAxes() {
  return (appData.adverbScales && appData.adverbScales.axes) || [];
}

function _scaleDrillCount(axisId) {
  const all = appData.exercises['module_adverbs'] || [];
  return all.filter(ex => ex.type === 'scale_choice' &&
    (!axisId || ex.exercise_id.startsWith('ex_adv_scale_' + axisId + '_'))).length;
}

function _scaleChips(axis) {
  if (axis.layout === 'grid') return axis.cells.flat(2);
  return axis.tiers.flatMap(t => t.words);
}

function openAdverbScales() { navigateTo('screen-adverb-scales'); }

function openAdverbScale(axisId) {
  _scaleAxisId = axisId;
  // navigateTo() ignores a jump to the screen already showing, so re-render instead
  if (currentScreen === 'screen-adverb-scale') { renderAdverbScale(); window.scrollTo(0, 0); return; }
  navigateTo('screen-adverb-scale');
}

// ── List ────────────────────────────────────────────────────────────────────
function renderAdverbScales() {
  const axes = _scaleAxes();
  const el = document.getElementById('adverb-scales-content');
  if (!el) return;
  const drills = _scaleDrillCount(null);

  el.innerHTML = `
    <div class="heading-lg" style="margin-bottom:var(--sp-2)">Skalen</div>
    <p class="scale-intro">Adverbien in Beziehung: jede Skala stellt eine Frage
      und ordnet die Wörter von einem Pol zum anderen.</p>

    ${drills > 0 ? `
    <div class="category-card mt-4" style="cursor:pointer" onclick="openExercise('module_adverbs','scales')">
      <div class="category-card-title">Alle Skalen üben</div>
      <div class="category-card-subtitle">Welches Wort ist stärker, häufiger, früher?</div>
      <div class="category-card-count mt-3">${drills} Übungen</div>
      <div class="category-card-cta">Üben →</div>
    </div>` : ''}

    <div class="label mt-4" style="margin-bottom:var(--sp-3)">${axes.length} Skalen</div>
    ${axes.map(ax => {
      const chips = _scaleChips(ax);
      const ends = ax.layout === 'grid'
        ? `${_esc(ax.rows[0])} ↔ ${_esc(ax.rows[ax.rows.length - 1])}`
        : `${_esc(ax.tiers[0].words[0].w)} … ${_esc(ax.tiers[ax.tiers.length - 1].words[0].w)}`;
      return `
      <div class="card scale-list-card" onclick="openAdverbScale('${ax.id}')">
        <div style="flex:1;min-width:0">
          <div class="scale-list-title">${_esc(ax.title)}
            ${ax.evidence === 'rule_of_thumb' ? '<span class="tag scale-tag-rot">Faustregel</span>' : ''}</div>
          <div class="scale-list-q">${_esc(ax.question_de)}</div>
          <div class="scale-list-ends">${ends} · ${chips.length} Wörter</div>
        </div>
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"
             stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"
             style="color:var(--color-text-muted);flex-shrink:0;margin-left:var(--sp-3)">
          <polyline points="9 18 15 12 9 6"/>
        </svg>
      </div>`;
    }).join('')}`;
}

// ── Detail ──────────────────────────────────────────────────────────────────
function _scaleChipHtml(c, glossId) {
  const unv = c.status === 'unverified'
    ? '<sup class="scale-chip-unv" title="Not verified against Wiktionary">?</sup>' : '';
  return `<button class="scale-chip" data-gloss="${glossId}"
            data-word="${_esc(c.w)}" data-en="${_esc(c.en)}"
            onclick="toggleScaleGloss(this)">${_esc(c.w)}${unv}</button>`;
}

function toggleScaleGloss(btn) {
  const box = document.getElementById(btn.dataset.gloss);
  if (!box) return;
  const same = box.dataset.word === btn.dataset.word && box.style.display !== 'none';
  document.querySelectorAll(`.scale-chip[data-gloss="${btn.dataset.gloss}"]`)
    .forEach(b => b.classList.remove('active'));
  if (same) { box.style.display = 'none'; box.dataset.word = ''; return; }
  btn.classList.add('active');
  box.dataset.word = btn.dataset.word;
  box.innerHTML = `<strong>${_esc(btn.dataset.word)}</strong> — ${_esc(btn.dataset.en)}`;
  box.style.display = 'block';
}

function _scaleHighlight(sentence, word) {
  const s = _esc(sentence), w = _esc(word);
  const i = s.indexOf(w);
  return i < 0 ? s : s.slice(0, i) + '<strong>' + w + '</strong>' + s.slice(i + w.length);
}

function _scaleNote(text) {
  const warn = text.startsWith('⚠');
  return `<div class="scale-note${warn ? ' scale-note-warn' : ''}">${_esc(text)}</div>`;
}

function _renderLinearAxis(ax) {
  return `
    <div class="scale-pole scale-pole-top">${_esc(ax.top)}</div>
    <div class="scale-axis">
      ${ax.tiers.map((t, i) => {
        const gid = `sg-${ax.id}-${i}`;
        const ex = t.example && t.example.de;
        const showExample = ex && (!t.anchor || t.example.de !== t.anchor.de);
        return `
        <div class="scale-tier">
          <div class="scale-dot" style="--pos:${ax.tiers.length > 1 ? i / (ax.tiers.length - 1) : 0}"></div>
          <div class="scale-tier-head">
            <span class="scale-tier-label">${_esc(t.label)}</span>
            <span class="scale-tier-en">${_esc(t.label_en)}</span>
          </div>
          <div class="scale-chips">${t.words.map(c => _scaleChipHtml(c, gid)).join('')}</div>
          <div class="scale-gloss" id="${gid}" style="display:none"></div>
          ${t.anchor ? `
            <div class="scale-anchor">
              <div class="example-de">${_scaleHighlight(t.anchor.de, t.anchor.word)}</div>
              <div class="example-en">${_esc(t.anchor.en)}</div>
            </div>` : ''}
          ${showExample ? `
            <div class="scale-example">
              <div class="scale-example-de">${_scaleHighlight(t.example.de, t.words[0].w)}</div>
              <div class="scale-example-en">${_esc(t.example.en)}</div>
            </div>` : ''}
          ${t.note ? _scaleNote(t.note) : ''}
        </div>`;
      }).join('')}
    </div>
    <div class="scale-pole scale-pole-bottom">${_esc(ax.bottom)}</div>`;
}

function _renderGridAxis(ax) {
  // Transposed for a 375px screen: one row per column-category, so a 4-column grid
  // reads as four short lines (Zeit: immer → irgendwann → nie) instead of a wide table.
  return `
    <div class="scale-grid" style="--cols:${ax.rows.length};--head:${Math.max(...ax.cols.map(c => c.length)) * 8 + 10}px">
      <div class="scale-grid-row scale-grid-head">
        <div></div>
        ${ax.rows.map((r, i) => `<div><span class="scale-tier-label">${_esc(r)}</span>
          <span class="scale-tier-en">${_esc(ax.rows_en[i])}</span></div>`).join('')}
      </div>
      ${ax.cols.map((col, c) => {
        const gid = `sg-${ax.id}-c${c}`;
        return `
        <div class="scale-grid-row">
          <div class="scale-grid-col"><span class="scale-tier-label">${_esc(col)}</span>
            <span class="scale-tier-en">${_esc(ax.cols_en[c])}</span></div>
          ${ax.rows.map((_, r) => `<div class="scale-chips">
              ${ax.cells[r][c].map(ch => _scaleChipHtml(ch, gid)).join('')}</div>`).join('')}
        </div>
        <div class="scale-gloss scale-grid-gloss" id="${gid}" style="display:none"></div>`;
      }).join('')}
    </div>`;
}

function renderAdverbScale() {
  const ax = _scaleAxes().find(a => a.id === _scaleAxisId);
  const el = document.getElementById('adverb-scale-content');
  if (!el) return;
  if (!ax) { el.innerHTML = '<div class="empty-state"><p>Skala nicht gefunden.</p></div>'; return; }
  const nav = document.getElementById('adverb-scale-nav');
  if (nav) nav.textContent = 'Skala · ' + ax.title;
  const drills = _scaleDrillCount(ax.id);

  el.innerHTML = `
    <div class="heading-lg">${_esc(ax.title)}</div>
    <div class="scale-question">${_esc(ax.question_de)}</div>
    <div class="scale-question-en">${_esc(ax.question_en)}</div>
    ${ax.evidence === 'rule_of_thumb' ? `
      <div class="scale-note"><span class="tag scale-tag-rot">Faustregel</span>
        Dictionaries treat these words as near-synonyms; the order here is a learner's rule
        of thumb, not a dictionary ranking.</div>` : ''}
    <div class="scale-hint">Tippe ein Wort für die Bedeutung.</div>

    <div class="card scale-card">
      ${ax.layout === 'grid' ? _renderGridAxis(ax) : _renderLinearAxis(ax)}
    </div>

    ${ax.side && ax.side.length ? `
      <div class="label mt-4" style="margin-bottom:var(--sp-2)">Gut zu wissen</div>
      ${ax.side.map((s, i) => `
        <div class="card scale-side">
          <div class="scale-side-text">${_esc(s.text)}</div>
          ${s.words.length ? `
            <div class="scale-chips mt-2">${s.words.map(c => _scaleChipHtml(c, `sg-${ax.id}-s${i}`)).join('')}</div>
            <div class="scale-gloss" id="sg-${ax.id}-s${i}" style="display:none"></div>` : ''}
        </div>`).join('')}` : ''}

    ${drills > 0 ? `
      <button class="primary-btn mt-4" onclick="openExercise('module_adverbs','scale:${ax.id}')">
        Diese Skala üben · ${drills}</button>` : ''}
    <div style="height:var(--sp-8)"></div>`;
}
